tool_input.old_string:
    fn empty_leaf() -> Self {
        OctreeNode::Leaf { entries: Vec::new() }
    }

    fn count(&self) -> usize {
        match self {
            OctreeNode::Leaf { entries } => entries.len(),
            OctreeNode::Interior { children } => {
                children.iter().map(|c| c.as_ref().map_or(0, |n| n.count())).sum()
            }
        }
    }
}

tool_input.new_string:
    fn empty_leaf() -> Self {
        OctreeNode::Leaf { entries: Vec::new() }
    }
}
